const body = $input.first().json.body || $input.first().json;

// 1. Check staff_id
if (!body.staff_id || typeof body.staff_id !== 'string' || body.staff_id.trim() === '') {
  return [{
    json: {
      isValid: false,
      errorType: 'MISSING_STAFF_ID',
      statusCode: 400,
      response: {
        status: 'error',
        code: 'MISSING_STAFF_ID',
        error: 'missing staff_id',
        message: "Mandatory parameter 'staff_id' is missing or empty."
      }
    }
  }];
}

// 2. Check class_id
if (!body.class_id || typeof body.class_id !== 'string' || body.class_id.trim() === '') {
  return [{
    json: {
      isValid: false,
      errorType: 'MISSING_CLASS_ID',
      statusCode: 400,
      response: {
        status: 'error',
        code: 'MISSING_CLASS_ID',
        error: 'missing class_id',
        message: "Mandatory parameter 'class_id' is missing or empty."
      }
    }
  }];
}

// 3. Check dates
const obs = body.observation_period || {};
const startDate = obs.start_date || '2026-10-12';
const endDate = obs.end_date || '2026-10-23';

const isoDateRegex = /^\d{4}-\d{2}-\d{2}$/;
if (!isoDateRegex.test(startDate) || !isoDateRegex.test(endDate)) {
  return [{
    json: {
      isValid: false,
      errorType: 'INVALID_DATES',
      statusCode: 400,
      response: {
        status: 'error',
        code: 'INVALID_DATES',
        error: 'invalid dates',
        message: "Dates must follow YYYY-MM-DD format."
      }
    }
  }];
}

if (new Date(startDate) > new Date(endDate)) {
  return [{
    json: {
      isValid: false,
      errorType: 'INVALID_DATES',
      statusCode: 400,
      response: {
        status: 'error',
        code: 'INVALID_DATES',
        error: 'invalid dates',
        message: `start_date (${startDate}) cannot be after end_date (${endDate}).`
      }
    }
  }];
}

const thresholdCount = (body.attendance_threshold && body.attendance_threshold.absence_threshold_count) ? parseInt(body.attendance_threshold.absence_threshold_count, 10) : 8;

return [{
  json: {
    isValid: true,
    staff_id: body.staff_id.trim(),
    class_id: body.class_id.trim(),
    student_id: body.student_id ? body.student_id.trim() : null,
    start_date: startDate,
    end_date: endDate,
    threshold_count: thresholdCount
  }
}];

const rows = $input.all();
const inputData = $('Validate Input').first().json;

if (!rows || rows.length === 0) {
  return [{
    json: {
      isAuthorized: false,
      statusCode: 403,
      response: {
        status: 'error',
        code: 'UNAUTHORIZED_STAFF',
        error: 'unauthorized staff',
        message: `Staff member '${inputData.staff_id}' does not exist or is inactive.`
      }
    }
  }];
}

const staff = rows[0].json;
const isInstitutionalRole = ['counselor', 'admin', 'support_lead'].includes(staff.role);
const hasClassViewPerm = (staff.can_view === true || staff.can_view === 'true');

if (!isInstitutionalRole && !hasClassViewPerm) {
  return [{
    json: {
      isAuthorized: false,
      statusCode: 403,
      response: {
        status: 'error',
        code: 'UNAUTHORIZED_STAFF',
        error: 'unauthorized staff',
        message: `Access Denied (TC3): Staff member '${staff.full_name}' (${staff.role}) is not authorized to access records for class '${inputData.class_id}'.`
      }
    }
  }];
}

return [{
  json: {
    isAuthorized: true,
    staff_id: inputData.staff_id,
    staff_role: staff.role,
    staff_name: staff.full_name,
    class_id: inputData.class_id,
    student_id: inputData.student_id,
    start_date: inputData.start_date,
    end_date: inputData.end_date,
    threshold_count: inputData.threshold_count
  }
}];

const rows = $input.all();
const authData = $('Evaluate Authorization (TC3)').first().json;

if (authData.student_id && (!rows || rows.length === 0)) {
  return [{
    json: {
      studentFound: false,
      statusCode: 404,
      response: {
        status: 'error',
        code: 'UNKNOWN_STUDENT',
        error: 'unknown student',
        message: `Student with ID '${authData.student_id}' not found in class '${authData.class_id}'.`
      }
    }
  }];
}

const studentsList = rows.map(r => r.json);

return [{
  json: {
    studentFound: true,
    students: studentsList,
    meta: authData
  }
}];

const attendanceRows = $('Fetch Attendance Records').all().map(r => r.json);
const leaveRows = $('Fetch Approved Leave Records').all().map(r => r.json);
const studentContext = $('Check Student Exists').first().json;
const meta = studentContext.meta;
const students = studentContext.students;

// Group attendance by student
const studentMap = {};
for (const s of students) {
  studentMap[s.student_id] = {
    student_id: s.student_id,
    student_code: s.student_code,
    first_name: s.first_name,
    last_name: s.last_name,
    class_name: s.class_name,
    total_sessions: 0,
    present_count: 0,
    tardy_count: 0,
    unexcused_absences: 0,
    excused_medical_absences: 0,
    covered_leave_refs: []
  };
}

for (const att of attendanceRows) {
  const st = studentMap[att.student_id];
  if (!st) continue;

  st.total_sessions++;
  if (att.status === 'present') {
    st.present_count++;
  } else if (att.status === 'tardy') {
    st.tardy_count++;
  } else if (att.status === 'absent' || att.status === 'half_day') {
    // Check if covered by approved leave (Rule 102 & TC2)
    const matchingLeave = leaveRows.find(l => 
      l.student_id === att.student_id && 
      att.date >= l.start_date && 
      att.date <= l.end_date
    );

    if (matchingLeave) {
      st.excused_medical_absences++;
      if (!st.covered_leave_refs.includes(matchingLeave.documentation_ref)) {
        st.covered_leave_refs.push(matchingLeave.documentation_ref);
      }
    } else {
      st.unexcused_absences++;
    }
  }
}

const triageResults = [];
let flaggedCount = 0;
let medicalShieldedCount = 0;

for (const sId in studentMap) {
  const item = studentMap[sId];
  const threshold = meta.threshold_count;

  // Rule 103 (TC1)
  const isFlagRaised = item.unexcused_absences >= threshold;

  // Rule 102 (TC2): Total absences >= 8 but excused medical subtracted
  const totalAbsences = item.unexcused_absences + item.excused_medical_absences;
  const isShieldedByMedical = (!isFlagRaised && totalAbsences >= threshold && item.excused_medical_absences > 0);

  let decisionReason = 'Normal attendance stability within configured threshold.';
  let recommendation = 'no_action_needed';

  if (isFlagRaised) {
    flaggedCount++;
    decisionReason = `TC1 TRIGGER: Sustained attendance pattern change detected (${item.unexcused_absences} of ${item.total_sessions} sessions unattended without documented exception).`;
    recommendation = 'create_private_counsellor_review_proposal';
  } else if (isShieldedByMedical) {
    medicalShieldedCount++;
    decisionReason = `TC2 SHIELD: ${totalAbsences} unattended sessions observed, but ${item.excused_medical_absences} covered by approved medical documentation (${item.covered_leave_refs.join(', ')}). Excluded from triage flag.`;
    recommendation = 'no_action_needed_medical_exception';
  }

  triageResults.push({
    student_id: item.student_id,
    student_code: item.student_code,
    class_name: item.class_name,
    telemetry: {
      total_sessions_evaluated: item.total_sessions,
      present_count: item.present_count,
      tardy_count: item.tardy_count,
      unexcused_absences: item.unexcused_absences,
      excused_medical_absences: item.excused_medical_absences,
      effective_attendance_rate_pct: item.total_sessions > 0 
        ? Math.round(((item.present_count + item.excused_medical_absences) / item.total_sessions) * 1000) / 10 
        : 100.0
    },
    triage_evaluation: {
      threshold_tested: `${threshold} unexcused absences`,
      flag_raised: isFlagRaised,
      is_medical_shielded: isShieldedByMedical,
      decision_reason: decisionReason,
      recommended_action: recommendation
    },
    ethical_compliance: {
      zero_labelling_verified: true,
      punitive_action: 'NONE',
      public_flag: false,
      privacy_quarantine: 'counselor_only'
    }
  });
}

return [{
  json: {
    status: 'success',
    timestamp: new Date().toISOString(),
    request_scope: {
      evaluated_by_staff: meta.staff_name,
      staff_role: meta.staff_role,
      class_id: meta.class_id,
      observation_period: {
        start_date: meta.start_date,
        end_date: meta.end_date
      },
      absence_threshold: meta.threshold_count
    },
    summary_metrics: {
      students_evaluated: triageResults.length,
      support_proposals_warranted: flaggedCount,
      medical_exceptions_shielded: medicalShieldedCount
    },
    triage_results: triageResults
  }
}];

const input = $input.first().json;
const results = input.triage_results || [];
const reqScope = input.request_scope || {};
const obs = reqScope.observation_period || {};
const windowDays = obs.window_days || 10;
const threshold = reqScope.absence_threshold || 8;
const startDate = obs.start_date || '2026-10-12';
const endDate = obs.end_date || '2026-10-23';

for (const item of results) {
  const tel = item.telemetry || {};
  const isFlagRaised = item.triage_evaluation && item.triage_evaluation.flag_raised;
  const isShielded = item.triage_evaluation && item.triage_evaluation.is_medical_shielded;

  let explanation = '';
  if (isFlagRaised) {
    explanation = `Student ${item.student_code} accumulated ${tel.unexcused_absences} unexcused absences across ${tel.total_sessions_evaluated} evaluated sessions during the ${windowDays}-day observation window (${startDate} to ${endDate}), meeting or exceeding the pastoral threshold of ${threshold} unexcused absences. Attendance rate decreased to ${tel.effective_attendance_rate_pct}%. Approved medical exceptions accounted for ${tel.excused_medical_absences} sessions.`;
  } else if (isShielded) {
    explanation = `Student ${item.student_code} recorded ${(tel.unexcused_absences || 0) + (tel.excused_medical_absences || 0)} total absences across ${tel.total_sessions_evaluated} evaluated sessions (${startDate} to ${endDate}). However, ${tel.excused_medical_absences} sessions are covered by authorized medical leave (${(tel.covered_leave_refs || []).join(', ') || 'MED-LEAVE'}), reducing unexcused absences to ${tel.unexcused_absences}, strictly below the threshold of ${threshold}. Rule 102 medical protection applies.`;
  } else {
    explanation = `Student ${item.student_code} maintained stable attendance with ${tel.present_count} present sessions and ${tel.unexcused_absences} unexcused absences across ${tel.total_sessions_evaluated} evaluated sessions. Attendance rate is ${tel.effective_attendance_rate_pct}%, safely within normal baseline parameters.`;
  }

  const evidenceUsed = [
    `Observation Period: ${startDate} to ${endDate} (${windowDays} calendar days)`,
    `Total Evaluated Sessions: ${tel.total_sessions_evaluated} sessions`,
    `Unexcused Absences: ${tel.unexcused_absences} sessions`,
    `Excused Medical Absences: ${tel.excused_medical_absences} sessions (Leave refs: ${(tel.covered_leave_refs || []).join(', ') || 'None'})`,
    `Configured Policy Threshold: ${threshold} unexcused absences`,
    `Effective Attendance Rate: ${tel.effective_attendance_rate_pct}%`
  ];

  const uncertainty = isFlagRaised
    ? 'Underlying causes for absences (such as transit disruptions, undisclosed health events, or family care needs) are not documented in raw attendance logs. No unsupported assumptions or predictive extrapolations are made.'
    : isShielded
    ? 'Approved medical documentation is on file for the designated dates. Post-recovery academic catch-up status or transition needs are undocumented in attendance telemetry.'
    : 'No missing information or anomalous absence telemetry identified.';

  const nextStep = isFlagRaised
    ? 'Conduct an informal, private 10-minute supportive check-in during morning advisory period to ask student how the school can support their attendance.'
    : isShielded
    ? 'No intervention flag required. Counselors may optionally verify post-recovery academic catch-up materials are accessible to the student.'
    : 'Maintain regular roll-call monitoring; no pastoral outreach required at this time.';

  item.ai_explanation = {
    explanation,
    evidence_used: evidenceUsed,
    uncertainty_or_missing_info: uncertainty,
    suggested_supportive_next_step: nextStep,
    is_private: true,
    generated_by: 'Gemini via n8n Message a model node',
    timestamp: new Date().toISOString()
  };
}

return [{ json: input }];
